(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.25)*18 + Math.cos(y*0.013-t*0.18)*12;
  const w1y = Math.cos(y*0.016-t*0.22)*18 + Math.sin(x*0.014+t*0.3)*12;
  const w2x = Math.sin((x+y)*0.008+t*0.15)*8 + Math.cos((x-y)*0.012-t*0.4)*6;
  const w2y = Math.cos((x-y)*0.009+t*0.35)*8 + Math.sin((x+y)*0.011+t*0.12)*6;
  const sx = x + w1x + w2x, sy = y + w1y + w2y;
  const src = [
    [160+Math.sin(t*0.5)*110, 80+Math.cos(t*0.35)*55, 0.075, 2.1, 1.0],
    [320+Math.cos(t*0.45)*110, 160+Math.sin(t*0.6)*55, 0.09, 1.8, 0.9],
    [240+Math.sin(t*0.28+2)*150, 120+Math.cos(t*0.45+1)*95, 0.055, 2.5, 1.1],
    [120+Math.cos(t*0.7+1)*85, 180+Math.sin(t*0.55+3)*65, 0.11, 1.6, 0.85],
    [360+Math.sin(t*0.38+4)*95, 60+Math.cos(t*0.8+2)*75, 0.065, 2.8, 1.05],
    [240+Math.cos(t*0.32+5)*130, 200+Math.sin(t*0.5)*85, 0.085, 2.0, 0.95],
    [80+Math.sin(t*0.6+3)*70, 40+Math.cos(t*0.4+5)*60, 0.1, 1.4, 0.8],
    [400+Math.cos(t*0.55+2)*80, 200+Math.sin(t*0.65+1)*70, 0.07, 2.3, 1.15]
  ];
  let aS = 0, iS = 0, cross = 0;
  for (let j = 0; j < src.length; j++) {
    const [sX, sY, f, sp, w] = src[j];
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    const a = Math.sin(d*f - t*sp);
    const i = Math.sin(d*f*0.65 + t*sp*0.55 + 1.7);
    aS += a * w; iS += i * w;
    for (let k = j+1; k < src.length; k++) {
      const [sX2, sY2] = src[k];
      const d2 = Math.sqrt((sx-sX2)**2 + (sy-sY2)**2);
      cross += Math.sin((d+d2)*0.04 - t*1.2) * w * src[k][4] * 0.15;
    }
  }
  const n = src.length;
  const act = aS/n, inh = iS/n;
  const bg1 = (Math.sin(sx*0.035+sy*0.022+t*0.7) + Math.sin(sx*0.028-sy*0.035+t*0.95))/2;
  const bg2 = Math.sin((sx+sy)*0.1+t*2.2)*0.25 + Math.sin((sx-sy)*0.085-t*1.8)*0.25;
  const turb = Math.sin(sx*0.06+t*1.5)*Math.sin(sy*0.055-t*1.3)*0.3;
  const bg = bg1 + bg2 + turb;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2);
  const ang = Math.atan2(sy-cy, sx-cx);
