  const sp2 = Math.sin(dist*0.035+ang*4.5-t*1.0);
  const sp3 = Math.sin(dist*0.07-ang*2-t*2.5)*0.3;
  const spiral = (sp1+sp2)*0.35 + sp3;
  const diff = Math.tanh((act - inh*0.65 + bg*0.28 + spiral*0.35 + cross)*2.0);
  const cell = Math.tanh((Math.sin(sx*0.13)*Math.sin(sy*0.13) + Math.sin((sx+sy)*0.09+t)*0.4 + Math.sin(sx*0.08-t*0.7)*Math.sin(sy*0.1+t*0.5)*0.3)*1.4)*0.3;
  const fine = Math.sin(sx*0.25+t*3)*Math.sin(sy*0.22-t*2.5)*0.08;
  const blend = diff*0.6 + cell*0.3 + fine;
  const v = blend*0.5+0.5;
  const pal = [
    [5,12,52],[10,45,85],[12,85,105],[18,135,130],
    [80,165,120],[180,175,70],[210,140,60],[195,85,65],
    [140,45,75],[70,18,55],[30,10,42],[5,12,52]
  ];
  const idx = v*(pal.length-1);
  const i = Math.min(idx|0, pal.length-2);
  const f = idx-i;
  const rBase = pal[i][0]+(pal[i+1][0]-pal[i][0])*f;
  const gBase = pal[i][1]+(pal[i+1][1]-pal[i][1])*f;
  const bBase = pal[i][2]+(pal[i+1][2]-pal[i][2])*f;
  const lum = 0.75+Math.sin(diff*Math.PI)*0.25;
  const edge = Math.abs(diff)>0.65 ? 1.2 : (Math.abs(diff)>0.3 ? 1.05 : 0.95);
  const shimmer = 1.0 + Math.sin(t*4+dist*0.1)*0.04*Math.abs(diff);
  const m = lum*edge*shimmer;
  return [
    Math.min(255, rBase*m)|0,
    Math.min(255, gBase*m)|0,
    Math.min(255, bBase*m)|0
  ];
}
